import{_ as t,c as n,j as e,a as _,o as l}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第九十七章 枣子大小土块中的尘土多吗？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/97第九十七章 枣子大小土块中的尘土多吗.md","filePath":"meditation/巴利文大藏经/97第九十七章 枣子大小土块中的尘土多吗.md"}'),r={name:"meditation/巴利文大藏经/97第九十七章 枣子大小土块中的尘土多吗.md"};function o(s,a,i,d,p,c){return l(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第九十七章-枣子大小土块中的尘土多吗",tabindex:"-1"},[_("第九十七章 枣子大小土块中的尘土多吗？ "),e("a",{class:"header-anchor",href:"#第九十七章-枣子大小土块中的尘土多吗","aria-label":'Permalink to "第九十七章 枣子大小土块中的尘土多吗？"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部13相应6经/地经第二(现观相应/因缘篇/如来记说)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，如果大地除了七颗枣子大小的土块外，其余大地所有的尘土全部都灭尽、消失了，弟子们，你们现在是怎么想的？是灭尽、消失的大地尘土多，还是残留的七颗枣子大小的土块包含的尘土多？",-1),e("p",null,"出家弟子们回答：“世尊，当然是灭尽、消失的大地尘土更多，残留的七颗枣子大小的土块包含的尘土更少。灭尽、消失的大地尘土是残留七颗枣子大小土块中尘土的百倍、千倍、十万倍、无数倍。残留的七颗枣子大小的土块包含的尘土与灭尽、消失的大地尘土相比可以忽略不计。”",-1),e("p",null,"佛陀说：“同样的道理，弟子们，具足正确见解，已经证悟初果（初果解释，见第七十章）及以上果位的圣弟子们，他们灭尽、灭除的烦恼和痛苦很多，他们灭尽的烦恼和痛苦就如同灭尽、消失的大地尘土那么多，他们残留的烦恼和痛苦非常的少，他们残留的烦恼和痛苦就如同残留的七颗枣子大小土块中包含的尘土那样少。弟子们，也就是说已经证悟初果的圣弟子们，他们残留的烦恼和痛苦比不上他们灭尽烦恼和痛苦的百分之一、千分之一、十万分之一，他们残留的烦恼和痛苦与他们灭尽的烦恼和痛苦相比可以忽略不计。这些已经证悟初果的圣弟子们，他们最多在人间和天界往返七次，就能永远的从生死轮回中解脱出来，也就是说已经证悟初果的圣弟子们，他们最多再有七次的生死轮回，就能除灭一切的烦恼和痛苦，就能从这个世间永远的解脱出来，就能从生死轮回中永远的解脱出来。弟子们，具足正确的见解，证悟初果就能获得这么大的功德利益，明白了如来所说的正法，就能获得这么大的功德利益。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
